	@Query(value ="SELECT  te.id, te.manual_id, em.id AS btExpenseManagementId,em.manual_id AS btExpenseManagementManualId, bd.business_domain_id AS businessDomainId,bd.business_domain_name AS businessDomainName,te.mode_of_travel_id AS modeOfTravelId, mt.name AS modeOfTravelName, te.own_conveyance_id AS ownConveyanceId,oc.name AS ownConveyanceName, te.departure_date AS departureDate, te.departure_time AS departureTime, te.arrival_date AS arrivalDate,te.arrival_time AS arrivalTime, te.from_place AS fromPlace, te.to_place AS toPlace, te.company_paid AS companyPaid,te.fare,te.approved_amount AS approvedAmount,te.distance,te.remark,te.no_of_days AS noOfDays, te.created_by_email_id AS createdByEmailId,CONCAT(IFNULL(ed.`first_name`,' '),IFNULL(ed.`middle_name`,' '),IFNULL(ed.`last_name`,''))AS `createdByName`,te.created_date AS createdDate,te.last_modified_by_email_id AS lastModifiedByEmailId, CONCAT(IFNULL(ed.`first_name`,' '),IFNULL(ed.`middle_name`,' '),IFNULL(ed.`last_name`,''))AS `modifiedByName`, te.last_modified_date AS lastModifiedDate, te.owner_email_id AS ownerEmailId,CONCAT(IFNULL(ed.`first_name`,' '),IFNULL(ed.`middle_name`,' '),IFNULL(ed.`last_name`,''))AS `ownerByName`,te.amount_to_disbursed FROM bt_tour_expense te LEFT JOIN bt_expense_management em ON te.bt_expense_management_id=em.id LEFT JOIN mode_of_travel mt ON mt.id=te.mode_of_travel_id LEFT JOIN own_conveyance oc ON oc.id=te.own_conveyance_id LEFT JOIN employee_details ed ON te.created_by_email_Id=ed.email_id LEFT JOIN business_domain bd ON bd.business_domain_id=em.business_domain_business_domain_id  WHERE te.is_deleted=FALSE and te.id=:id",nativeQuery = true)
	Map<String, Object> getById(@Param("id")long id);
	
